using Godot;
using System;
using System.Threading.Tasks;
public partial class MigrationScene {
 int crashAck;
 [Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopCrashAck(int step){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))crashAck=Math.Max(crashAck,step);}
 async Task CrashCoopChecks(CoopActor actor){crashFixture=true;game.World.Changes.Crash=new();var home=HostPosition;Teleport(ExpeditionCrash.X(game.World),ExpeditionCrash.Z);SpawnCrash();actor.Body.Position=crashRoot.ToGlobal(new Vector3(0,0,3.4f));RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(actor.Game),"",actor.Body.Position,true);CrashSync();RpcId(actor.Id,nameof(CoopCheckStage),"crash-trunk",actor.Body.Position);await CoopWait(()=>crashAck>=1,"Guest trunk/rabbit missing",15);if(paused||!Crash.Toy||Crash.Choice!=0)throw new Exception("Crash trunk affected host UI or branch");actor.Body.Position=crashRoot.ToGlobal(new Vector3(2,0,.3f));RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(actor.Game),"",actor.Body.Position,true);RpcId(actor.Id,nameof(CoopCheckStage),"crash-choice",actor.Body.Position);await CoopWait(()=>crashAck>=2,"Guest crash choice missing",15);if(paused||Crash.Choice!=1||!actor.Game.Profile.Journal.Seen.Contains("crash/truth"))throw new Exception("Crash choice/journal isolation failed");crashFixture=false;Teleport(home.X,home.Z);actor.Body.Position=HostPosition+Vector3.Right*3;RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(actor.Game),"",actor.Body.Position,true);GD.Print("PASS / two-process crash: guest trunk, rabbit, handoff, shared first-choice-wins and personal dialogue/journal");}
 async Task ClientCrashChecks(string stage,Vector3 target){crashFixture=true;await CoopWait(()=>Distance(player.Position,target)<1,"Crash teleport missing",15);SpawnCrash();if(stage=="crash-trunk"){CoopRequest("crash","trunk");await CoopWait(()=>paused&&Crash.Opened,"Guest trunk dialogue missing");CrashChoice("take");await CoopWait(()=>Crash.Toy&&!paused,"Guest rabbit missing");RpcId(1,nameof(CoopCrashAck),1);}else{
 // Establish the girl interaction on the authority before committing the handoff.
 // A late pose from the trunk may arrive after the test teleport correction.
 double deadline=Time.GetTicksMsec()/1000.0+10;
 while(!paused){CoopRequest("crash","girl");await CoopDelay(.25);if(Time.GetTicksMsec()/1000.0>deadline)throw new Exception("Guest girl dialogue missing after crash teleport");}
 CrashChoice("give");await CoopWait(()=>paused&&Crash.Given,"Guest handoff missing");CrashChoice("truth");await CoopWait(()=>paused&&Crash.Choice==1&&game.Profile.Journal.Seen.Contains("crash/truth"),"Guest branch/journal missing");CloseMenu();CoopRequest("crash","secret");await CoopDelay(.2);if(Crash.Choice!=1)throw new Exception("Second crash choice overwrote first");RpcId(1,nameof(CoopCrashAck),2);crashFixture=false;}}
}
